solution.solution.cpp:
#include <string_view>
#include <vector>

bool balanced(std::string_view text)
{
    std::vector<char> open{};
    for (char c : text)
    {
        if (c == '(' || c == '[' || c == '{')
        {
            open.push_back(c);
        }
        else if (c == ')' || c == ']' || c == '}')
        {
            if (open.empty())
            {
                return false;
            }
            const char top{ open.back() };
            open.pop_back();
            const bool matches{ (top == '(' && c == ')') || (top == '[' && c == ']') || (top == '{' && c == '}') };
            if (!matches)
            {
                return false;
            }
        }
    }
    return open.empty();
}

unitTests:
TEST("balanced") { CHECK(balanced("{[()()]}")); CHECK(balanced("()[]{}")); CHECK(balanced("")); }
TEST("other characters are ignored") { CHECK(balanced("int main() { return v[0]; }")); }
TEST("overlapping") { CHECK(!balanced("([)]")); CHECK(!balanced("{(})")); }
TEST("never closed") { CHECK(!balanced("((")); CHECK(!balanced("{[]")); }
TEST("closed before opened") { CHECK(!balanced(")(")); CHECK(!balanced("]")); }

